inputs = ['bwuj', 'vu', 'iux', 'yhc', 'vw']
outputs = ['bbhfbuj', 'vu', 'aub', 'yazc', 'vbhfb']

print("Detailed analysis of differences:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"'{inp}' -> '{out}'")
    # Let's see what needs to be added/changed
    if len(inp) < len(out):
        # Some characters were added
        print(f"  Length diff: +{len(out)-len(inp)} chars")
    elif len(inp) > len(out):
        # Some characters were removed
        print(f"  Length diff: -{len(inp)-len(out)} chars")
    else:
        print("  Same length")

